#define _DARWIN_C_SOURCE 1
#include <errno.h>
#include <inttypes.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <sys/event.h>
#include <sys/socket.h>
#include <unistd.h>
#define LIMIT 65536
static _Atomic unsigned tracked_fd[LIMIT];
typedef struct queue_stats {
    _Alignas(64) _Atomic uint64_t adopted, thread, reads, bytes, read_thread;
} queue_stats;
static queue_stats stats[LIMIT];
static _Thread_local uint64_t cached_thread;
static uint64_t current_thread(void) {
    if (!cached_thread) (void)pthread_threadid_np(NULL, &cached_thread);
    return cached_thread;
}
static int traced_kevent(int queue, const struct kevent *changes, int change_count,
                         struct kevent *events, int event_count, const struct timespec *timeout) {
    int result = kevent(queue, changes, change_count, events, event_count, timeout);
    int saved_errno = errno;
    if (result >= 0 && queue >= 0 && queue < LIMIT) {
        for (int i = 0; i < change_count; ++i) {
            const struct kevent *event = &changes[i];
            if (event->filter != EVFILT_READ || !(event->flags & EV_ADD) || event->ident >= LIMIT) continue;
            int fd = (int)event->ident;
            if (atomic_load(&tracked_fd[fd])) continue;
            struct sockaddr_storage peer; socklen_t peer_size = sizeof(peer);
            if (getpeername(fd, (struct sockaddr *)&peer, &peer_size) < 0) continue;
            uint64_t thread = current_thread();
            atomic_store(&tracked_fd[fd], (unsigned)queue + 1u);
            atomic_store(&stats[queue].thread, thread); atomic_fetch_add(&stats[queue].adopted, 1);
        }
    }
    errno = saved_errno; return result;
}
static ssize_t traced_recv(int fd, void *bytes, size_t size, int flags) {
    ssize_t result = recv(fd, bytes, size, flags);
    int saved_errno = errno;
    if (result > 0 && fd >= 0 && fd < LIMIT) {
        unsigned entry = atomic_load(&tracked_fd[fd]);
        if (entry && entry <= LIMIT) {
            unsigned queue = entry - 1u;
            atomic_store(&stats[queue].read_thread, current_thread());
            atomic_fetch_add_explicit(&stats[queue].reads, 1, memory_order_relaxed);
            atomic_fetch_add_explicit(&stats[queue].bytes, (uint64_t)result, memory_order_relaxed);
        }
    }
    errno = saved_errno; return result;
}
static int traced_close(int fd) {
    if (fd >= 0 && fd < LIMIT) atomic_store(&tracked_fd[fd], 0);
    return close(fd);
}
__attribute__((destructor)) static void report(void) {
    for (int q = 0; q < LIMIT; ++q) if (atomic_load(&stats[q].adopted))
        fprintf(stderr, "ADOPT_TRACE queue=%d adopted=%" PRIu64 " thread=%" PRIu64 " positive_reads=%" PRIu64 " read_bytes=%" PRIu64 " read_thread=%" PRIu64 "\n", q, atomic_load(&stats[q].adopted), atomic_load(&stats[q].thread), atomic_load(&stats[q].reads), atomic_load(&stats[q].bytes), atomic_load(&stats[q].read_thread));
}
#define INTERPOSE(replacement, original) \
    __attribute__((used, section("__DATA,__interpose"))) \
    static const struct { const void *replacement_fn; const void *original_fn; } \
    interpose_##replacement = {(const void *)replacement, (const void *)original}
INTERPOSE(traced_kevent, kevent);
INTERPOSE(traced_close, close);

INTERPOSE(traced_recv, recv);
